#include<bits/stdc++.h>
using namespace std;
const int maxn =1e5 + 5;
string a;
// 矢量版邻接矩阵 , 存每个点的邻接点
vector<int> e[maxn];
// sz , r 含义如上
int sz[maxn] , r[maxn];
// 第一遍 dfs 求出每个点的 sz 和 r 
void dfs1 (int u , int fa){
    sz[u] = 1;
    r[u] = a[u] == 'R';
    for (auto v : e[u]){
        if (v == fa) continue;
        dfs1(v , u);
        sz[u] += sz[v];
        r[u] += r[v];
    }
    return ;
}
// 第二遍 枚举每条边(u,v)
int ans = 0;
void dfs2 (int u , int fa){
    for (auto v : e[u]){
        if (v == fa) continue;
        dfs2(v , u);
        // 判断子树是否合法
        if (r[v] <= sz[v] - r[v]) continue;
        // 判断主树是否合法
        int rest_sz = sz[1] - sz[v];
        int rest_r = r[1] - r[v];
        if (rest_r <= rest_sz - rest_r) continue;
        // 都合法，则这条边可以，答案 + 1
        ans++;
    }
    return ;
}
int main (){
    int n;
    cin >> n;
    cin >> a;
    // 读入
    a = '#' + a;
    for (int i = 1 ; i < n ; i++){
        int x , y;
        cin >> x >> y;
        e[x].push_back(y);
        e[y].push_back(x);
    }
    dfs1(1 , -1);
    dfs2(1 , -1);
    cout << ans << endl;
    return 0;
}
